import {stageAt} from './svg.js';
export const topic={number:'08',title:'封裝微流道單相液冷',question:'流體帶走晶片熱量之後，熱到哪裡去？',duration:32,overview:20,simplification:'參考IBM單晶片模組的單相矽微流道冷卻器，選用銀填充環氧（Ag epoxy）接合於晶片背面。主圖用一條代表流道的縱剖面呈現晶片→接合層→矽壁→流體的連續熱路；外部泵與換熱器是概念迴路改編，未重現論文的管路尺寸。裝置已充液且持續循環；金框短段只是同一小段流體的追蹤標記，不是氣泡或固體顆粒。色溫、速度、流道厚度與熱箭頭均為定性示意，不求解壓降、湍流或三維流場，也不引用為性能量測。',supplement:'<p>泵提供流動所需壓差，換熱器把熱交給外部環境。穩態只代表平均狀態可維持，晶片仍持續發熱、流體仍持續帶走熱量，並不代表各處完全同溫。每32秒只重複觀察順序，同一封裝、流向及溫度分布保持連續。</p>',sources:[{title:'IBM Research · Silicon microchannel cooling for high power chips (2006)',url:'https://research.ibm.com/publications/silicon-microchannel-cooling-for-high-power-chips',claim:'原研究摘要：單相矽微流道、單晶片模組與Ag epoxy接合界面。外部迴路為本動畫的概念延伸，不沿用未核對的性能數字。'}]};
export const stages=[{start:0,key:4,title:'熱穿過接合層與矽壁',explain:'晶片持續發熱，橙色箭頭沿晶片、銀填充環氧及矽壁進入流體。',detail:'封裝正面的小銅接點在下方；水被封在上方流道與管路內，不碰電接點。'},{start:8,key:12,title:'流道吸熱，流體向出口移動',explain:'較冷水由左側入口進入，在流道中吸熱後由右側出口離開。金框短段隨同一方向走完整迴路。',detail:'藍色箭頭表示流向，橙色箭頭表示熱流。全程為單相液體，沒有沸騰氣泡。'},{start:16,key:20,title:'溫熱流體走向外部換熱器',explain:'帶熱的水仍在畫面中的封閉管路內，從右側往上到換熱器。',detail:'沒有把溫熱流體直接隱藏掉；熱與流體皆有可追蹤的去向。'},{start:24,key:28,title:'向環境放熱，泵送較冷回流',explain:'外部換熱器把熱傳給環境，水變得較冷，再沿左側由泵送回入口。',detail:'泵驅動流動，冷卻來自把熱交給環境。觀察順序重複時不把晶片或流體溫度歸零。'}];
export function stateAt(t){const index=stageAt(t,stages);return{t,index,title:stages[index].title,phase:(t%8)/8,pulse:.75+.15*Math.sin(t*Math.PI/2),caption:'持續運作 · 單相水冷迴路'};}
